#[test]
fn point_arithmetic() {
    let a = PowerRatio::from_base(6.0);
    let b = PowerRatio::from_base(2.0);
    let d: Level = a - b;
    assert_eq!(d.as_base(), 4.0);
    assert_eq!(b + d, a);
    assert_eq!(d + b, a);
    assert_eq!(a - d, b);
    assert_eq!(a / b, 3.0);
    let mut c = b;
    c += d;
    assert_eq!(c, a);
    c -= d;
    assert_eq!(c, b);
    let i: Level<i64> = PowerRatio::<i64>::from_base(7) - PowerRatio::from_base(2);
    assert_eq!(i.as_base(), 5);
}
